  line(ctx, [[2, -216], [2, -232]], C.ink, 4, .1);
  if (lance) { line(ctx, [[-30, -110], [190, -230]], '#6e4a2c', 7, .2); shape(ctx, [[190, -230], [214, -246], [196, -222]], '#cfd3d6', C.ink, 2, .1);
    const f = Math.sin(ph * 1.5) * 8; shape(ctx, [[150, -208], [110 + f, -236], [150, -226]], MAML, C.ink, 2, .2); }
