  ell(ctx, -6, 4, 34, 34, '#8b6a45', C.ink, 5); ell(ctx, -6, 4, 8, 8, C.ink, null);
  if (fire > 0 && fire < 1) { ctx.globalAlpha = 1 - fire; shape(ctx, [[96, -38], [150 + fire * 40, -70], [140, -38], [170 + fire * 60, -20], [100, -30]], '#f8d25a', '#e2572b', 4, 3); ctx.globalAlpha = 1; }
